fn rewrite_macro_call(&mut self, mac: &mut verus_syn::Macro) {
    if self.inside_ghost > 0 {
        if let Some(x) = mac.path.segments.first_mut() {
            let mut ident = x.ident.to_string();
            // NOTE: This is currently hardcoded for the macros
            //  * `open_local_invariant`,
            //  * `open_atomic_invariant`,
            //  * `open_atomic_update`,
            //  * `peek_atomic_update`, and
            //  * `try_open_atomic_update`
            // but this could be extended to rewrite other macro
            // names depending on proof vs exec mode.
            if let "open_local_invariant"
            | "open_atomic_invariant"
            | "open_atomic_update"
            | "peek_atomic_update"
            | "try_open_atomic_update" = ident.as_str()
            {
                ident.push_str("_in_proof");
                x.ident = Ident::new(&ident, x.span());
            }
        }
    };
}

fn visit_stmt_extend(&mut self, stmt: &mut Stmt) -> (bool, Vec<Stmt>) {
    let span = stmt.span();
    match stmt {
        Stmt::Local(local) => self.visit_local_extend(local),
        Stmt::Item(Item::BroadcastUse(broadcast_use)) => {
            let BroadcastUse { attrs, paths, .. } = broadcast_use;
            if self.erase_ghost.erase() {
                (true, vec![])
            } else {
                let stmts: Vec<Stmt> = paths.iter().map(|path| Stmt::Expr(Expr::Verbatim(
                    quote_spanned_builtin!(verus_builtin, span => #verus_builtin::reveal_hide_({#[verus::internal(reveal_fn)] fn __VERUS_REVEAL_INTERNAL__() { #verus_builtin::reveal_hide_internal_path_(#path) } #[verus::internal(broadcast_use_reveal)] __VERUS_REVEAL_INTERNAL__}, 1); )
                ), None)).collect();
                let mut attrs = attrs.clone();
                if self.inside_ghost == 0 {
                    attrs.push(mk_verus_attr(span, quote! { proof_block }));
                }
                let block = Stmt::Expr(
                    Expr::Block(ExprBlock {
                        attrs: attrs,
                        label: None,
                        block: Block { brace_token: token::Brace(span), stmts },
                    }),
                    None,
                );
                (true, vec![block])
            }
        }
        Stmt::Macro(macro_stmt) => {
            self.rewrite_macro_call(&mut macro_stmt.mac);
            (false, vec![])
        }
        _ => (false, vec![]),
