pub(crate) fn inv_au_macro_exprs(
    erase_ghost: EraseGhost,
    treat_elements_as_ghost: bool,
    ghost_override_index: usize,
    stream: proc_macro::TokenStream,
) -> proc_macro::TokenStream {
    let stream = rejoin_tokens(stream);
    let mut invoke: MacroInvoke = parse_macro_input!(stream as MacroInvoke);
    let mut new_stream = TokenStream::new();
    let mut visitor = Visitor {
        erase_ghost,
        use_spec_traits: true,
        inside_ghost: 0,
        inside_type: 0,
        inside_external_code: 0,
        inside_const: false,
        inside_arith: InsideArith::None,
        assign_to: false,
        rustdoc: env_rustdoc(),
        inside_impl: None,
        additional_items: Vec::new(),
    };

    invoke
        .elements
        .elements
        .iter_mut()
        .filter_map(|elem| match elem {
            MacroElement::Expr(expr) => Some(expr),
            _ => None,
        })
        .enumerate()
        .for_each(|(idx, expr)| {
            // Always treat the element at `ghost_override_index` as ghost
            // even if `treat_elements_as_ghost` is false.
            let ghost = treat_elements_as_ghost || idx == ghost_override_index;
            visitor.inside_ghost = u32::from(ghost);
            visitor.visit_expr_mut(expr);
        });

    invoke.to_tokens(&mut new_stream);
    proc_macro::TokenStream::from(new_stream)
}

pub(crate) fn proof_macro_explicit_exprs(
    erase_ghost: EraseGhost,
    inside_ghost: bool,
    stream: proc_macro::TokenStream,
) -> proc_macro::TokenStream {
    let stream = rejoin_tokens(stream);
    let mut invoke: MacroInvokeExplicitExpr = parse_macro_input!(stream as MacroInvokeExplicitExpr);
    let mut new_stream = TokenStream::new();
    let mut visitor = Visitor {
        erase_ghost,
        use_spec_traits: true,
        inside_ghost: if inside_ghost { 1 } else { 0 },
        inside_type: 0,
        inside_external_code: 0,
        inside_const: false,
        inside_arith: InsideArith::None,
        assign_to: false,
        rustdoc: env_rustdoc(),
        inside_impl: None,
        additional_items: Vec::new(),
    };
    for element in &mut invoke.elements.elements {
        match element {
            MacroElementExplicitExpr::ExplicitExpr(_at1, _at2, expr) => {
                visitor.visit_expr_mut(expr)
            }
            _ => {}
        }
    }
    invoke.to_tokens(&mut new_stream);
    proc_macro::TokenStream::from(new_stream)
}

